function importSave(){let file=document.getElementById('saveFile').files[0];if(!file){toast('Choose a save file first.');return}let r=new FileReader();r.onload=()=>{try{let d=JSON.parse(r.result);if(d.version!==1||typeof d.answered!=='number'||typeof d.correct!=='number'||typeof d.points!=='number'||!d.topics)throw Error('Invalid save format');if(!confirm('Import this save and replace progress in this browser?'))return;let safeAnswered=Math.max(0,Math.floor(d.answered)),safeCorrect=Math.min(safeAnswered,Math.max(0,Math.floor(d.correct)));data={version:1,answered:safeAnswered,correct:safeCorrect,points:Math.max(0,Math.floor(d.points)),bestStreak:Math.max(0,Math.floor(d.bestStreak||0)),streak:0,topics:{}};for(let t of topics){let s=d.topics[t.id]||{};let sa=Math.max(0,Math.floor(s.answered||0));data.topics[t.id]={answered:sa,correct:Math.min(sa,Math.max(0,Math.floor(s.correct||0))),points:Math.max(0,Math.floor(s.points||0))}}saveData();if(d.extras&&typeof d.extras==='object'){extras={...extrasDefault,...d.extras};saveExtras()}toast('Progress imported.')}catch(e){toast('That save file is not valid.')}};r.readAsText(file)}
function resetProgress(){if(!confirm('Delete all progress, bookmarks, mistakes and flashcard ratings stored in this browser? This cannot be undone unless you exported a save.'))return;data=fresh();extras={...extrasDefault};saveExtras();saveData();renderBreakdown();renderAchievements();renderMastery();toast('Local progress reset.')}
