function renderDashboard(){let ranked=topics.map(t=>({t,s:topicStat(t.id),acc:topicStat(t.id).answered?topicStat(t.id).correct/topicStat(t.id).answered:0})).sort((a,b)=>a.acc-b.acc);let weak=ranked.find(x=>x.s.answered>0);document.getElementById('recommendTitle').textContent=weak?'Try '+weak.t.name:'Start with a topic';document.getElementById('recommendText').textContent=weak?`Your current accuracy is ${Math.round(weak.acc*100)}%. Practising this topic could help strengthen your overall score.`:'Complete some questions and BYTE will suggest a topic to revisit.';document.getElementById('recommendBtn').onclick=()=>weak?startQuiz(weak.t.id):showView('topics');let since=new Date();since.setHours(0,0,0,0);since.setDate(since.getDate()-6);let recent=extras.activity.filter(x=>new Date(x.date+'T00:00:00')>=since);let recentAttempts=recent.reduce((n,x)=>n+(x.count||1),0),recentCorrect=recent.reduce((n,x)=>n+(x.correct||0),0);document.getElementById('weekAttempts').textContent=recentAttempts;document.getElementById('weekAccuracy').textContent=recentAttempts?Math.round(recentCorrect/recentAttempts*100)+'%':'0%';document.getElementById('masteredCount').textContent=topics.filter(t=>{let st=topicStat(t.id);return st.answered>=20&&st.correct/st.answered>=.8}).length+'/8'}
