const achievements=[['first','First steps','Answer your first question','attempts',1],['ten','Getting started','Answer 10 questions','attempts',10],['hundred','Century','Answer 100 questions','attempts',100],['perfect','Perfect start','Get 10 correct answers','correct',10],['streak','On a roll','Reach a 10-answer streak','streak',10],['points','Point collector','Earn 500 points','points',500],['explorer','Explorer','Try all 8 topics','topics',8],['master','Topic master','Master any one topic','master',1],['exam','Exam ready','Complete a mock exam','exam',1]];
