const flashcards=[['Bit','A binary digit. It can have a value of 0 or 1.'],['Byte','A group of 8 bits.'],['Denary','The base-10 number system, using digits 0 to 9.'],['Binary','The base-2 number system, using only 0 and 1.'],['Hexadecimal','The base-16 number system, using 0 to 9 and A to F.'],['Pixel','The smallest addressable element of a digital image.'],['Colour depth','The number of bits used to represent the colour of each pixel.'],['Sample rate','The number of sound samples taken per second.'],['Bit depth','The number of bits used for each sound sample.'],['ASCII','A character encoding that represents a limited set of characters.'],['Unicode','A character standard designed to represent characters across many writing systems.'],['Algorithm','A precise sequence of steps used to solve a problem.'],['Iteration','Repeating a set of instructions.'],['Selection','Choosing which instructions run based on a condition.'],['Sequence','Instructions carried out in order.'],['LAN','A local area network covering a limited geographical area.'],['WAN','A wide area network covering a large geographical area.'],['Router','A device that forwards data between different networks.'],['DNS','A system that looks up IP addresses for domain names.'],['Phishing','An attempt to trick someone into revealing information or taking an unsafe action.'],['Encryption','The process of converting information into a form that cannot be easily understood without a key.'],['Boolean','A data type with two possible values: True and False.'],['Variable','A named storage location used by a program.'],['Function','A reusable block of code that can perform a task and return a value.'],['Array/list','An ordered collection of items.'],['AND gate','Outputs 1 only when both inputs are 1.'],['OR gate','Outputs 1 when at least one input is 1.'],['XOR gate','Outputs 1 when the inputs are different.'],['Compiler','Translates source code into another form, often machine code, before execution.'],['Interpreter','Executes source code, often one statement at a time.']];
let flashIndex=0;function renderFlashcard(){let due=flashcards.map((c,i)=>({c,i,score:extras.flashRatings[i]||'new'})).sort((a,b)=>({again:0,new:1,good:2}[a.score]-({again:0,new:1,good:2}[b.score])));let item=due[flashIndex%due.length];flashIndex=item.i;document.getElementById('flashTerm').textContent=item.c[0];document.getElementById('flashAnswer').textContent=item.c[1];document.getElementById('flashcard').classList.remove('revealed');document.getElementById('flashcardCount').textContent=`Card ${flashIndex+1} / ${flashcards.length}`}
