function runSearch(){let q=document.getElementById('siteSearch').value.trim().toLowerCase();if(!q){toast('Type something to search for.');return}let hits=[];flashcards.forEach((c,i)=>{if((c[0]+' '+c[1]).toLowerCase().includes(q))hits.push({title:c[0],desc:c[1],action:`showView('flashcards');flashIndex=${i};renderFlashcard()`,kind:'Flashcard'})});topics.forEach(t=>{if((t.name+' '+t.desc).toLowerCase().includes(q))hits.push({title:t.name,desc:t.desc,action:`startQuiz('${t.id}')`,kind:'Topic'});for(let level=0;level<3;level++){let qs=makeQuestions(t.id,level);qs.forEach(x=>{if((x.q+' '+x.e).toLowerCase().includes(q)&&hits.length<35)hits.push({title:x.q,desc:x.e,action:`startQuiz('${t.id}')`,kind:t.name})})}});document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));document.querySelectorAll('.navbtn').forEach(b=>b.classList.remove('active'));let main=document.getElementById('mainContent');let old=document.getElementById('searchView');if(old)old.remove();let sec=document.createElement('section');sec.id='searchView';sec.className='view active';sec.innerHTML=`<div class="section-head"><div><div class="eyebrow">SEARCH RESULTS</div><h2>Results for “${escapeHtml(q)}”</h2><p>${hits.length} matching topics or practice questions.</p></div><button class="btn" onclick="showView('home');document.getElementById('searchView')?.remove()">Back home</button></div><div class="search-results">${hits.length?hits.map(h=>`<button class="panel search-result" onclick="${h.action}"><span class="chip">${escapeHtml(h.kind)}</span><h3 style="margin-top:8px">${escapeHtml(h.title)}</h3><p>${escapeHtml(h.desc)}</p></button>`).join(''):'<div class="panel setting"><h3>No results found</h3><p>Try a different keyword, such as binary, network, loop or hexadecimal.</p></div>'}</div>`;main.appendChild(sec);window.scrollTo(0,0)}
function reportCurrentQuestion(){let q=questions[qIndex];let reason=prompt('What is wrong or confusing about this question?');if(reason===null)return;let body=`BYTE question report\nTopic: ${activeTopic}\nQuestion: ${q.q}\nExpected answer: ${q.a}\nReport details: ${reason}\n`; let blob=new Blob([body],{type:'text/plain'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='byte-question-report.txt';a.click();URL.revokeObjectURL(url);toast('Report template downloaded. Add details before sending it to the site creator.')}
// Exam mode
let exam={items:[],index:0,answers:[],seconds:1200,timer:null,ended:false};
function beginExam(){let level=document.getElementById('examLevel').value,count=+document.getElementById('examLength').value;
 // Build a unique question pool from all topics with fresh random seeds, then pick `count` distinct questions without repeats.
 let rng=createRng((Math.random()*4294967295)>>>0),pool=[],seen=new Set();
 for(let guard=0;pool.length<count&&guard<60;guard++){
  topics.forEach(t=>{let lv=level==='mix'?Math.floor(rng()*3):+level;let set=makeQuestions(t.id,lv);set.forEach(x=>{let k=t.id+'|'+x.q;if(!seen.has(k)){seen.add(k);pool.push({...x,topic:t.id,options:null})}})});
 }
 shuffle(pool,rng);
 exam.items=pool.slice(0,count);
 exam.index=0;exam.answers=Array(exam.items.length).fill(null);exam.seconds=1200;exam.ended=false;document.getElementById('examSetup').style.display='none';document.getElementById('examResult').innerHTML='';document.getElementById('examRun').style.display='block';renderExamQuestion();clearInterval(exam.timer);exam.timer=setInterval(()=>{exam.seconds--;document.getElementById('examTimer').textContent=Math.floor(exam.seconds/60)+':'+String(exam.seconds%60).padStart(2,'0');if(exam.seconds<=0)finishExam()},1000)}
function renderExamQuestion(){let q=exam.items[exam.index];document.getElementById('examCounter').textContent=`Question ${exam.index+1} / ${exam.items.length}`;document.getElementById('examQuestion').textContent=q.q;let box=document.getElementById('examAnswers');box.innerHTML=`<input id="examInput" placeholder="Type your answer…" value="${escapeHtml(exam.answers[exam.index]||'')}" style="width:100%">`;document.getElementById('examProgress').textContent=exam.answers.filter(x=>x!==null&&x!=='').length+' answered';let btn=document.querySelector('#examRun .quiz-bottom button');btn.textContent=exam.index===exam.items.length-1?'Submit exam':'Next →'}
function nextExamQuestion(){let inp=document.getElementById('examInput');exam.answers[exam.index]=inp.value.trim();if(exam.index<exam.items.length-1){exam.index++;renderExamQuestion()}else finishExam()}
function finishExam(){if(exam.ended)return;let currentInput=document.getElementById('examInput');if(currentInput)exam.answers[exam.index]=currentInput.value.trim();exam.ended=true;clearInterval(exam.timer);let correct=0;let review=[];exam.items.forEach((q,i)=>{let ok=norm(exam.answers[i]||'')===norm(q.a),st=topicStat(q.topic);st.answered++;if(ok){correct++;st.correct++;st.points+=10}else extras.mistakes.unshift({topic:q.topic,q:q.q,a:q.a,e:q.e,date:new Date().toISOString()});review.push(`<div class="result-row"><span>${i+1}. ${escapeHtml(q.q)}</span><span>${ok?'✓':'✗'} ${escapeHtml(q.a)}</span></div>`)});extras.mistakes=extras.mistakes.slice(0,100);extras.examBest=Math.max(extras.examBest,correct);recordActivity(correct,exam.items.length);saveExtras();data.answered+=exam.items.length;data.correct+=correct;data.points+=correct*10;saveData();document.getElementById('examRun').style.display='none';document.getElementById('examSetup').style.display='block';document.getElementById('examSetup').innerHTML=`<div class="eyebrow">EXAM COMPLETE</div><h2>${correct} / ${exam.items.length}</h2><p>${Math.round(correct/exam.items.length*100)}% score · ${correct*10} points earned</p><button class="btn primary" onclick="resetExam()">Try another exam →</button>`;document.getElementById('examResult').innerHTML=`<div class="panel setting" style="margin-top:14px"><h3>Answer review</h3>${review.join('')}</div>`;renderAchievements()}
function resetExam(){document.getElementById('examSetup').innerHTML='<h3>Set up your mock exam</h3><div class="tool-controls" style="margin:14px 0"><label for="examLevel">Difficulty</label><select id="examLevel"><option value="0">Beginner · Year 7–8</option><option value="1" selected>Intermediate · Year 9–10</option><option value="2">Advanced · Year 11</option><option value="mix">Mixed levels</option></select><label for="examLength">Questions</label><select id="examLength"><option value="10">10 questions</option><option value="20" selected>20 questions</option><option value="30">30 questions</option></select></div><button class="btn primary" onclick="beginExam()">Start exam →</button>';document.getElementById('examResult').innerHTML=''}
// Daily challenge, generated consistently for the local calendar date.
let daily={items:[],index:0,correct:0,answered:false,results:[]};function prepareDaily(){let date=localDateKey();document.getElementById('dailyDate').textContent=date;let done=extras.dailyDone.includes(date);document.getElementById('dailyStatus').textContent=done?'You have completed today’s challenge. Come back tomorrow for a new set.':'Complete all 10 questions to finish today’s challenge.';document.getElementById('dailyStart').disabled=done;document.getElementById('dailySetup').style.display='block';document.getElementById('dailyRun').style.display='none'}
function startDaily(){let day=localDateKey()+'|'+getStudentId(),seed=hashStr(day),rng=createRng(seed);daily.items=[];let used=new Set();for(let i=0;i<10;i++){let t=topics[Math.floor(rng()*topics.length)],lv=Math.floor(rng()*3),set=makeQuestions(t.id,lv,hashStr(seed+'q'+i+'_'+t.id));let chosen=set.find(x=>!used.has(t.id+'|'+x.q))||set[0];used.add(t.id+'|'+chosen.q);daily.items.push({...chosen,topic:t})}daily.index=0;daily.correct=0;daily.answered=false;daily.results=[];document.getElementById('dailySetup').style.display='none';document.getElementById('dailyRun').style.display='block';document.getElementById('dailyResult').innerHTML='';renderDaily()}
function renderDaily(){let q=daily.items[daily.index];document.getElementById('dailyCounter').textContent=`Question ${daily.index+1} / 10`;document.getElementById('dailyTopic').textContent=q.topic.name;document.getElementById('dailyQuestion').textContent=q.q;document.getElementById('dailyAnswer').value='';document.getElementById('dailyAnswer').disabled=false;document.getElementById('dailyFeedback').className='feedback';document.getElementById('dailyNext').disabled=true;document.getElementById('dailyNext').textContent=daily.index===9?'Finish →':'Next →';daily.answered=false}
function answerDaily(){if(daily.answered)return;let input=document.getElementById('dailyAnswer').value;if(!input.trim())return;daily.answered=true;let q=daily.items[daily.index],ok=norm(input)===norm(q.a);if(ok){daily.correct++;daily.results[daily.index]=true}else{daily.results[daily.index]=false;extras.mistakes.unshift({topic:q.topic.id,q:q.q,a:q.a,e:q.e,date:new Date().toISOString()});extras.mistakes=extras.mistakes.slice(0,100);saveExtras()}document.getElementById('dailyFeedback').className='feedback '+(ok?'good':'bad');document.getElementById('dailyFeedback').textContent=(ok?'Correct! ':'Not quite. Answer: '+q.a+'. ')+q.e;document.getElementById('dailyAnswer').disabled=true;document.getElementById('dailyNext').disabled=false;document.getElementById('dailyScore').textContent=daily.correct+' correct'}
function nextDaily(){if(!daily.answered)return;if(daily.index<9){daily.index++;renderDaily()}else{let date=localDateKey();if(!extras.dailyDone.includes(date))extras.dailyDone.push(date);saveExtras();data.answered+=10;data.correct+=daily.correct;data.points+=daily.correct*10;daily.items.forEach((q,i)=>{let st=topicStat(q.topic.id);st.answered++;if(daily.results[i]){st.correct++;st.points+=10}});recordActivity(daily.correct,10);saveData();document.getElementById('dailyRun').style.display='none';document.getElementById('dailyResult').innerHTML=`<div class="panel setting"><div class="eyebrow">DAILY CHALLENGE COMPLETE</div><h2>${daily.correct} / 10 correct</h2><p>Come back tomorrow for another set.</p></div>`;prepareDaily()}}
// Interactive tools
// Binary place-value practice and algorithm ordering.
const bitValues=[128,64,32,16,8,4,2,1];let bitState=Array(8).fill(0);function renderBitToggles(){document.getElementById('bitToggles').innerHTML=bitValues.map((v,i)=>`<button class="btn ${bitState[i]?'primary':''}" aria-label="Toggle ${v} bit" aria-pressed="${!!bitState[i]}" onclick="toggleBit(${i})"><b>${bitState[i]}</b><small style="display:block;font-size:9px">${v}</small></button>`).join('');let n=bitState.reduce((a,b,i)=>a+b*bitValues[i],0);document.getElementById('bitTotal').textContent=`Binary ${bitState.join('')} = ${n} denary`}
function toggleBit(i){bitState[i]=bitState[i]?0:1;renderBitToggles()}
const algorithmSteps=['Start at the first item in the list.','Check the current item against the target.','If it matches, report the position and stop.','If it does not match, move to the next item.','If the list ends, report that the target was not found.'];let algorithmOrder=[];function resetAlgorithmOrder(){algorithmOrder=[2,0,3,1,4];renderAlgorithmOrder();document.getElementById('algorithmResult').textContent='Arrange the steps, then check your answer.'}
function renderAlgorithmOrder(){document.getElementById('algorithmOrder').innerHTML=algorithmOrder.map((id,i)=>`<div class="result-row"><span>${i+1}. ${algorithmSteps[id]}</span><span><button class="btn" aria-label="Move step up" onclick="moveAlgorithm(${i},-1)" ${i===0?'disabled':''}>↑</button> <button class="btn" aria-label="Move step down" onclick="moveAlgorithm(${i},1)" ${i===algorithmOrder.length-1?'disabled':''}>↓</button></span></div>`).join('')}
function moveAlgorithm(i,d){let j=i+d;if(j<0||j>=algorithmOrder.length)return;[algorithmOrder[i],algorithmOrder[j]]=[algorithmOrder[j],algorithmOrder[i]];renderAlgorithmOrder()}
function checkAlgorithmOrder(){let ok=algorithmOrder.every((x,i)=>x===i);document.getElementById('algorithmResult').textContent=ok?'Correct. You have arranged the linear search steps in order.':'Not quite. Think about starting at the first item, checking it, then deciding what happens next.'}
function convertBinaryTool(){let n=Number(document.getElementById('binaryToolInput').value);let el=document.getElementById('binaryToolResult');if(!Number.isInteger(n)||n<0||n>255){el.textContent='Enter a whole number from 0 to 255.';return}el.textContent=`${n} denary = ${n.toString(2).padStart(8,'0')} binary = ${n.toString(16).toUpperCase().padStart(2,'0')} hexadecimal`}
function updateGateTool(){let gate=document.getElementById('gateType').value,a=+document.getElementById('gateA').value,b=+document.getElementById('gateB').value,showB=gate!=='NOT';document.getElementById('gateBLabel').style.display=showB?'inline-flex':'none';let out=gate==='AND'?a&b:gate==='OR'?a|b:gate==='NOT'?1-a:gate==='XOR'?a^b:gate==='NAND'?1-(a&b):1-(a|b);document.getElementById('gateResult').textContent=`${gate}(${a}${showB?', '+b:''}) = ${out}`}
let sortValues=[7,3,8,2,6,1,5],sortI=0,sortJ=0,sortDone=false;function drawSort(){let max=Math.max(...sortValues);document.getElementById('sortBars').innerHTML=sortValues.map((n,i)=>`<div title="${n}" style="flex:1;height:${n/max*100}%;min-width:8px;border-radius:5px 5px 0 0;background:var(--text);opacity:${(i===sortJ||i===sortJ+1)?0.95:0.55};display:flex;align-items:flex-start;justify-content:center;color:var(--bg);font-size:11px;padding-top:4px">${n}</div>`).join('')}
function resetSort(){sortValues=[7,3,8,2,6,1,5];sortI=0;sortJ=0;sortDone=false;document.getElementById('sortStatus').textContent='Ready';drawSort()}
function sortStep(){if(sortDone){document.getElementById('sortStatus').textContent='Already sorted';return}if(sortJ>=sortValues.length-sortI-1){sortJ=0;sortI++;if(sortI>=sortValues.length-1){sortDone=true;document.getElementById('sortStatus').textContent='Sorted!';drawSort();return}}if(sortValues[sortJ]>sortValues[sortJ+1]){[sortValues[sortJ],sortValues[sortJ+1]]=[sortValues[sortJ+1],sortValues[sortJ]];document.getElementById('sortStatus').textContent='Swapped adjacent values'}else document.getElementById('sortStatus').textContent='Compared, no swap';sortJ++;drawSort()}
let traceIndex=0;const traceLines=['Line 1 · total = 0','Line 2 · n = 2 · total = 2','Line 2 · n = 4 · total = 6','Line 2 · n = 6 · total = 12','Loop finished · total = 12'];function traceStep(){traceIndex=Math.min(traceIndex+1,traceLines.length-1);document.getElementById('traceResult').textContent=traceLines[traceIndex]}function resetTrace(){traceIndex=0;document.getElementById('traceResult').textContent=traceLines[0]}
// Keyboard shortcuts: / focuses search, H returns home, ? opens shortcut help.
addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select,[contenteditable="true"]'))return;if(e.key==='/'&&!e.ctrlKey&&!e.metaKey){e.preventDefault();document.getElementById('siteSearch').focus()}if(e.key.toLowerCase()==='h')showView('home');if(e.key==='?')toast('Shortcuts: / search · H home · Tab navigation · Enter activate')});

// Mouse-reactive constellation background. It does not animate continuously.
const canvas=document.getElementById('stars'),ctx=canvas.getContext('2d');let w,h,pts=[],mouse={x:-999,y:-999};
function resize(){w=canvas.width=innerWidth;h=canvas.height=innerHeight;pts=Array.from({length:Math.min(95,Math.floor(w*h/13000))},(_,i)=>({x:Math.random()*w,y:Math.random()*h,r:.6+Math.random()*1.1})) ;drawStars()}
function drawStars(){ctx.clearRect(0,0,w,h);for(let i=0;i<pts.length;i++){let p=pts[i],dx=p.x-mouse.x,dy=p.y-mouse.y,d=Math.hypot(dx,dy);if(d<150){ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(mouse.x,mouse.y);ctx.strokeStyle=`rgba(255,255,255,${(1-d/150)*.18})`;ctx.lineWidth=.7;ctx.stroke()}for(let j=i+1;j<pts.length;j++){let q=pts[j],dist=Math.hypot(p.x-q.x,p.y-q.y);if(dist<105){ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.strokeStyle=`rgba(255,255,255,${(1-dist/105)*.075})`;ctx.lineWidth=.6;ctx.stroke()}}ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fillStyle='rgba(255,255,255,.55)';ctx.fill()}}
addEventListener('resize',resize);addEventListener('mousemove',e=>{mouse.x=e.clientX;mouse.y=e.clientY;drawStars()});addEventListener('mouseleave',()=>{mouse.x=-999;mouse.y=-999;drawStars()});addEventListener('click',e=>{if(e.target.closest('button')&&!document.body.classList.contains('no-motion')&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){let r=document.createElement('span');r.className='click-ripple';r.style.left=e.clientX+'px';r.style.top=e.clientY+'px';document.body.appendChild(r);setTimeout(()=>r.remove(),500)}});
resize();applySettings();renderHome();renderTopics();renderStats();loadPyChallenge();updateGateTool();drawSort();resetTrace();renderBitToggles();resetAlgorithmOrder();prepareDaily();
// Mouse trail: subtle star-like specks along the cursor's path. They fade out shortly
// after the mouse stops, so the trail looks like it catches up to the cursor.
(function(){
 const trail=document.getElementById('trail');if(!trail)return;
 const tx=trail.getContext('2d');let tw,th,stars=[],running=false,raf=null;
 function resize(){tw=trail.width=innerWidth;th=trail.height=innerHeight}
 function disabled(){return document.body.classList.contains('no-motion')||window.matchMedia('(prefers-reduced-motion: reduce)').matches}
 function stop(){if(running){running=false;stars=[];cancelAnimationFrame(raf);raf=null;if(tx)tx.clearRect(0,0,tw,th)}}
 function drawStar(x,y,s,a){const r=s*2.2;tx.beginPath();tx.moveTo(x,y-r);tx.lineTo(x+r*.28,y-r*.28);tx.lineTo(x+r,y);tx.lineTo(x+r*.28,y+r*.28);tx.lineTo(x,y+r);tx.lineTo(x-r*.28,y+r*.28);tx.lineTo(x-r,y);tx.lineTo(x-r*.28,y-r*.28);tx.closePath();tx.fillStyle=`rgba(255,255,255,${a})`;tx.fill()}
 function tick(){
  if(disabled()){stop();return}
  tx.clearRect(0,0,tw,th);
  for(let i=stars.length-1;i>=0;i--){let st=stars[i];st.life--;if(st.life<=0)stars.splice(i,1);else drawStar(st.x,st.y,st.size,Math.min(1,st.life/st.max)*st.o)}
  if(stars.length)raf=requestAnimationFrame(tick);else{running=false;raf=null}
 }
 function wake(){if(disabled())return;if(!running){running=true;raf=requestAnimationFrame(tick)}}
 addEventListener('mousemove',e=>{
  if(disabled())return;
  const last=stars[stars.length-1];
  if(!last||Math.hypot(e.clientX-last.x,e.clientY-last.y)>7){
   stars.push({x:e.clientX,y:e.clientY,size:.8+Math.random()*1.2,o:.5+Math.random()*.4,max:22,life:22});
   if(stars.length>22)stars.splice(0,stars.length-22);
  }
  wake();
 });
 addEventListener('mouseleave',stop);addEventListener('resize',resize);
 resize();
}());
